## ✅ Quick “migration-in-one-file” example

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8" />
  <title>MapLibre + Draw + Geocoder</title>
  <link href="https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.css" rel="stylesheet" />
  <link href="https://unpkg.com/@maplibre/maplibre-gl-geocoder@^1.5.0/dist/maplibre-gl-geocoder.css" rel="stylesheet" />
  <link href="https://unpkg.com/@mapbox/mapbox-gl-draw@1.5.0/dist/mapbox-gl-draw.css" rel="stylesheet" />
  <style>
    #map { position:absolute; top:0; bottom:0; width:100%; }
  </style>
</head>
<body>
<div id="map"></div>

<script type="module">
  import * as maplibregl from 'https://unpkg.com/maplibre-gl@^6.0.0/dist/maplibre-gl.mjs';
  import MapboxDraw from 'https://unpkg.com/@mapbox/mapbox-gl-draw@1.5.0/dist/mapbox-gl-draw.mjs';
  import MaplibreGeocoder from 'https://unpkg.com/@maplibre/maplibre-gl-geocoder@^1.5.0/dist/maplibre-gl-geocoder.mjs';

  const map = new maplibregl.Map({
    container: 'map',
    style: 'https://tiles.openfreemap.org/styles/liberty',
    center: [-122.42, 37.78],
    zoom: 12
  });

  // ---- Draw -------------------------------------------------
  const draw = new MapboxDraw({
    displayControlsDefault: false,
    controls: { polygon: true, line_string: true, point: true, trash: true }
  });
  map.addControl(draw);

  // ---- Geocoder ---------------------------------------------
  const geocoder = new MaplibreGeocoder({
    placeholder: 'Search…',
    url: 'https://nominatim.openstreetmap.org/search',
    limit: 5,
    language: 'en'
  });
  map.addControl(geocoder);
</script>
</body>
</html>
```

*Run the page in a modern browser (MapLibre v6+ requires WebGL 2). The map loads, you can draw polygons/lines/points, and the search box works via Nominatim.*

